CREATE TABLE IF NOT EXISTS public.lead_memory ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, identifier TEXT NOT NULL, channel TEXT NOT NULL, identifier_type TEXT NOT NULL, name TEXT, email TEXT, phone TEXT, operacao TEXT, tipo_imovel TEXT, bairros TEXT[], quartos_min INTEGER, preco_max DECIMAL(12,2), preco_min DECIMAL(12,2), urgencia TEXT, perfil_credito TEXT, notas_extras TEXT, total_sessions INTEGER DEFAULT 1, last_interaction_at TIMESTAMPTZ DEFAULT NOW(), first_interaction_at TIMESTAMPTZ DEFAULT NOW(), imoveis_visualizados UUID[], imoveis_favoritos UUID[], status TEXT DEFAULT 'active', assigned_agent TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(tenant_id, identifier, channel) ); CREATE INDEX IF NOT EXISTS idx_lead_memory_lookup ON public.lead_memory(tenant_id, identifier, channel); CREATE INDEX IF NOT EXISTS idx_lead_memory_active ON public.lead_memory(tenant_id, status, last_interaction_at);
